SELECT 
FROM TBL_BOND_ISSUANCE
WHERE DELETE_FLAG = 0

    AND BOND_NO LIKE CONCAT('%', #{bondNo}, '%')


    AND BOND_NO LIKE CONCAT('%', #{issuanceNo}, '%')


    AND BOND_NAME LIKE CONCAT('%', #{bondName}, '%')


    AND BOND_TYPE = #{bondType}


    AND BOND_STATUS = #{bondStatus}


    AND BOND_STATUS = #{issuanceStatus}


    AND COMPANY_ID = #{companyId}


    AND CURRENCY_CODE = #{currencyCode}


    AND ISSUE_DATE >= TO_DATE(#{startDate}, 'YYYY-MM-DD')


    AND ISSUE_DATE <= TO_DATE(#{endDate}, 'YYYY-MM-DD')

ORDER BY CREATED_TIME DESC

SELECT BOND_TYPE AS "bondType", COUNT(*) AS "count", NVL(SUM(ISSUE_AMOUNT), 0) AS "amount" FROM TBL_BOND_ISSUANCE WHERE DELETE_FLAG = 0
AND COMPANY_ID = #{companyId}
GROUP BY BOND_TYPE ORDER BY COUNT(*) DESC

SELECT TO_CHAR(ISSUE_DATE, 'YYYY-MM') AS "month", COUNT(*) AS "issuanceCount", NVL(SUM(ISSUE_AMOUNT), 0) AS "issuanceAmount" FROM TBL_BOND_ISSUANCE WHERE DELETE_FLAG = 0 AND ISSUE_DATE IS NOT NULL AND ISSUE_DATE >= ADD_MONTHS(SYSDATE, -#{months})
AND COMPANY_ID = #{companyId}
GROUP BY TO_CHAR(ISSUE_DATE, 'YYYY-MM') ORDER BY TO_CHAR(ISSUE_DATE, 'YYYY-MM') ASC

SELECT 
FROM TBL_BOND_ISSUANCE
WHERE DELETE_FLAG = 0

    AND BOND_NO LIKE CONCAT('%', #{bondNo}, '%')


    AND BOND_NO LIKE CONCAT('%', #{issuanceNo}, '%')


    AND BOND_NAME LIKE CONCAT('%', #{bondName}, '%')


    AND BOND_TYPE = #{bondType}


    AND BOND_STATUS = #{bondStatus}


    AND BOND_STATUS = #{issuanceStatus}


    AND COMPANY_ID = #{companyId}

ORDER BY CREATED_TIME DESC
